syntax.code:
identifier  := ("_" | UnicodeLetter) { "_" | UnicodeLetter | UnicodeDigit }
comment     := "#" { nonNewline } | "//" { nonNewline }
string      := '"' { character | escape } '"'
escape      := "\\n" | "\\r" | "\\t" | "\\\\" | "\\\"" | "\\" character
separator   := whitespace | ";"

expression := prefix { binaryOp prefix }
prefix     := literal | identifier | list | block | tryExpr | matchExpr
            | ( "-" | "!" | "~" ) expression | "(" expression ")"
postfix    := expression { "(" [ arguments ] ")" | "." identifier | "?" }
list       := "[" [ expression { "," expression } ] "]"
block      := "{" { statement [ ";" ] } [ expression ] "}"

func double(value u32) u32 => value * u32(2)
func apply(value u32, callback func(u32) u32) u32 {
  return callback(value)
}
let callback func(u32) u32 = double
macro twice(value) => value + value

let result = ok(value)
let? unwrapped = result
let direct = result?
let recovered = try operation() catch err { err.kind }
let safe = redact(withdebug(error(IOError, "read"), "path", secret))

struct Name { field Type [`namespace:"value"`] … }
type Alias = ExistingType
newtype Name ExistingType
